1	import { DOCUMENT, Injectable, PLATFORM_ID, inject } from '@angular/core';
2	import { isPlatformBrowser } from '@angular/common';
3	import { Meta, Title } from '@angular/platform-browser';
4	import { ActivatedRoute, NavigationEnd, Router } from '@angular/router';
5	import { filter } from 'rxjs/operators';
6	
7	const SITE_URL = 'https://foovanteglobal.earth';
8	
9	const DEFAULT_TITLE = 'Foovante Global — African carbon markets, built right';
10	const DEFAULT_DESCRIPTION =
11	  'Foovante is the verification, marketplace, and capital layer for African carbon. High-integrity carbon credits across energy, forests, and blue carbon.';
12	const DEFAULT_OG_IMAGE = '/assets/images/logo_2.png';
13	const SITE_NAME = 'Foovante Global';
14	
15	interface RouteSeoData {
16	  title?: string;
17	  description?: string;
18	  ogImage?: string;
19	}
20	
21	@Injectable({ providedIn: 'root' })
22	export class SeoService {
23	  private router = inject(Router);
24	  private activatedRoute = inject(ActivatedRoute);
25	  private title = inject(Title);
26	  private meta = inject(Meta);
27	  private document = inject(DOCUMENT);
28	  private isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
29	
30	  init(): void {
31	    this.router.events
32	      .pipe(filter(event => event instanceof NavigationEnd))
33	      .subscribe(() => {
34	        this.update();
35	        this.scrollToTop();
36	      });
37	  }
38	
39	  private scrollToTop(): void {
40	    if (!this.isBrowser) return;
41	    // Respect in-page anchors (e.g. /#team) — don't override fragment scrolls.
42	    if (this.router.url.includes('#')) return;
43	    // Defer past view transitions so the scroll lands after the swap.
44	    queueMicrotask(() => window.scrollTo({ top: 0, left: 0, behavior: 'instant' as ScrollBehavior }));
45	  }
46	
47	  private update(): void {
48	    const data = this.readLeafData();
49	    const title = data.title ?? DEFAULT_TITLE;
50	    const description = data.description ?? DEFAULT_DESCRIPTION;
51	    const ogImage = this.absoluteUrl(data.ogImage ?? DEFAULT_OG_IMAGE);
52	    const canonical = SITE_URL + this.router.url.split('?')[0].split('#')[0];
53	
54	    this.title.setTitle(title);
55	
56	    this.meta.updateTag({ name: 'description', content: description });
57	
58	    this.setCanonical(canonical);
59	
60	    this.meta.updateTag({ property: 'og:title', content: title });
61	    this.meta.updateTag({ property: 'og:description', content: description });
62	    this.meta.updateTag({ property: 'og:url', content: canonical });
63	    this.meta.updateTag({ property: 'og:type', content: 'website' });
64	    this.meta.updateTag({ property: 'og:site_name', content: SITE_NAME });
65	    this.meta.updateTag({ property: 'og:image', content: ogImage });
66	
67	    this.meta.updateTag({ name: 'twitter:card', content: 'summary_large_image' });
68	    this.meta.updateTag({ name: 'twitter:title', content: title });
69	    this.meta.updateTag({ name: 'twitter:description', content: description });
70	    this.meta.updateTag({ name: 'twitter:image', content: ogImage });
71	  }
72	
73	  private readLeafData(): RouteSeoData {
74	    let route = this.activatedRoute;
75	    while (route.firstChild) {
76	      route = route.firstChild;
77	    }
78	    return (route.snapshot.data ?? {}) as RouteSeoData;
79	  }
80	
81	  private setCanonical(href: string): void {
82	    let link = this.document.querySelector('link[rel="canonical"]') as HTMLLinkElement | null;
83	    if (!link) {
84	      link = this.document.createElement('link');
85	      link.setAttribute('rel', 'canonical');
86	      this.document.head.appendChild(link);
87	    }
88	    link.setAttribute('href', href);
89	  }
90	
91	  private absoluteUrl(path: string): string {
92	    if (/^https?:\/\//i.test(path)) return path;
93	    return SITE_URL + (path.startsWith('/') ? path : '/' + path);
94	  }
95	}

